function procedureFields(config) {
  return [
    { id: 'side', label: 'Taraf / lokalizasyon', type: 'select', options: config.sides || ['Sağ', 'Sol', 'Bilateral'], sentence: (v) => `İşlem ${lower(v)} lokalizasyonda uygulandı.` },
    { id: 'finding', label: config.findingLabel || 'Temel intraoperatif bulgu', type: 'select', options: config.findings, sentence: (v) => `${config.findingLabel || 'İntraoperatif bulgu'} olarak ${lower(v)} saptandı.` },
    { id: 'severity', label: 'Bulgunun derecesi / yaygınlığı', type: 'select', options: ['Hafif', 'Orta', 'Belirgin', 'İleri / komplike'], sentence: (v) => `Bulguların derecesi ${lower(v)} olarak değerlendirildi.` },
    ...(config.measureLabel ? [{ id: 'measurement', label: config.measureLabel, type: 'number', placeholder: config.measureExample || 'Örn. 20', sentence: (v) => `${config.measureLabel.replace(/\s*\([^)]*\)/, '')} ${v} ${config.measureUnit || 'mm'} olarak ölçüldü.` }] : []),
    { id: 'tissue', label: config.tissueLabel || 'Doku canlılığı / görünümü', type: 'select', options: config.tissues || ['Normal', 'Ödemli / inflamatuvar', 'Konjesyone', 'Şüpheli canlılıkta', 'Nekrotik'], sentence: (v) => config.tissueLabel === 'Testiküler arter' ? `Testiküler arter ${lower(v)}.` : `${config.tissueLabel || 'Doku görünümü'} ${lower(v)} olarak izlendi.` },
    { id: 'action', label: config.actionLabel || 'Temel cerrahi işlem', type: 'select', options: config.actions, sentence: (v) => `${config.actionLabel || 'Cerrahi işlem'} olarak ${lower(v)}.` },
    { id: 'reconstruction', label: 'Onarım / rekonstrüksiyon', type: 'select', options: config.reconstructions || ['Gerekmedi', 'Primer onarım yapıldı', 'Anastomoz yapıldı', 'Yama / greft kullanıldı'], sentence: (v) => `Onarım ${lower(v)}.` },
    { id: 'criticalStructures', label: 'Kritik anatomik yapıların durumu', type: 'select', options: config.criticalStructures || ['Tanımlandı ve korundu', 'İşlem alanında değildi / tanımlanmadı', 'Görülmedi ancak yaralanma olmadı', 'Kısmi yaralanma gelişti ve onarıldı', 'Planlanan işlem gereği bağlandı / rezeke edildi'], sentence: (v) => `Kritik anatomik yapılar ${lower(v)}.` },
    { id: 'vascularStatus', label: 'Damar ve perfüzyon durumu', type: 'select', options: ['Ana damarlar tanımlandı ve korundu', 'Damarlar korunarak diseksiyon tamamlandı', 'Doppler ile akım doğrulandı', 'Damar yaralanması gelişmedi', 'Damar yaralanması gelişti ve onarıldı'], sentence: (v) => `Damar ve perfüzyon açısından ${lower(v)}.` },
    { id: 'nerveStatus', label: 'Sinir yapılarının durumu', type: 'select', options: ['Tanımlandı ve korundu', 'İşlem alanında değildi', 'Doğrudan görüntülenmedi ancak yaralanma olmadı', 'Nörolojik yapı yaralanması gelişti'], sentence: (v) => `Sinir yapıları ${lower(v)}.` },
    { id: 'organPreservation', label: 'Komşu organların korunması', type: 'select', options: ['Komşu organlar korundu', 'Komşu organ yaralanması izlenmedi', 'Komşu organ dikkatle ayrıldı ve korundu', 'Komşu organ yaralanması gelişti ve onarıldı', 'Planlı kombine rezeksiyon uygulandı'], sentence: (v) => `Komşu organlar açısından ${lower(v)}.` },
    { id: 'dissectionPlane', label: 'Diseksiyon planı', type: 'select', options: ['Doğal anatomik planda ilerlenebildi', 'İnflamasyon / fibrozis nedeniyle güç diseksiyon yapıldı', 'Adezyolizis gerekti', 'Güvenli plan bulunamadığı için işlem sınırlandırıldı'], sentence: (v) => `Diseksiyon ${lower(v)}.` },
    { id: 'plannedStep', label: 'Planlanan ana aşamanın sonucu', type: 'select', options: ['Tamamlandı', 'Ek manevra ile tamamlandı', 'Gerekmedi', 'Güvenlik nedeniyle uygulanmadı', 'Başka bir yönteme dönüştürüldü'], sentence: (v) => `Planlanan ana cerrahi aşama ${lower(v)}.` },
    { id: 'conversion', label: 'Cerrahi yaklaşım değişikliği', type: 'select', options: ['Gerekmedi', 'Laparoskopik / torakoskopik yaklaşımdan açığa dönüldü', 'Açık yaklaşımdan farklı tekniğe geçildi', 'İşlem planlandığı şekilde tamamlandı'], sentence: (v) => v === 'Gerekmedi' ? 'Yaklaşım değişikliğine gerek duyulmadı.' : `Cerrahi yaklaşım için ${lower(v)}.` },
    { id: 'leakTest', label: 'Kaçak / patensi kontrolü', type: 'select', options: ['Yapılmadı', 'Negatif', 'Pozitif, ek onarım yapıldı'], sentence: (v) => v === 'Yapılmadı' ? '' : `İntraoperatif kontrol ${lower(v)} sonuçlandı.` },
    { id: 'finalCheck', label: 'İşlem sonu anatomik kontrol', type: 'select', options: ['Hedef anatomi ve hemostaz doğrulandı', 'Ek sütür / klips sonrası doğrulandı', 'Şüpheli bulgu nedeniyle ek değerlendirme yapıldı', 'Yeterli görüntüleme sağlanamadı'], sentence: (v) => `İşlem sonunda ${lower(v)}.` },
    { id: 'drain', label: 'Dren / kateter', type: 'select', options: ['Konmadı', 'Dren kondu', 'Kateter / stent yerleştirildi'], sentence: (v) => v === 'Konmadı' ? 'Dren veya kateter konmadı.' : `${v}.` },
    { id: 'specimen', label: 'Patoloji spesimeni', type: 'select', options: ['Gönderilmedi', 'Patolojiye gönderildi', 'Kültüre gönderildi'], sentence: (v) => `Spesimen ${lower(v)}.` },
    { id: 'complication', label: 'İntraoperatif komplikasyon', type: 'select', options: ['Yok', 'Kanama', 'Komşu organ yaralanması', 'Seröz / mukoza yaralanması'], sentence: complicationSentence }
  ];
}

function registerAdditionalSchemas(entries) {
  entries.forEach(([key, label, techniques, config]) => {
    schemas[key] = { label, techniques, fields: procedureFields(config) };
  });
}

