const translationCache = new Map();

function escapeHtml(value) { return String(value).replace(/[&<>'"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[character]); }
async function translateText(text, language, source = 'tr') {
  if (!text || language === 'tr') return text;
  const cacheKey = `${source}:${language}:${text}`;
  if (translationCache.has(cacheKey)) return translationCache.get(cacheKey);
  try {
    const url = new URL('https://translate.googleapis.com/translate_a/single');
    url.searchParams.set('client', 'gtx');
    url.searchParams.set('sl', source);
    url.searchParams.set('tl', language);
    url.searchParams.set('dt', 't');
    url.searchParams.set('q', text);
    const response = await fetch(url);
    const data = await response.json();
    const translated = data?.[0]?.map((part) => part[0]).join('') || text;
    translationCache.set(cacheKey, translated);
    return translated;
  } catch {
    return text;
  }
}
async function translateMany(texts, language) {
  const sources = texts.map((text) => text || '');
  if (language === 'tr') return sources;
  const uniqueSources = [...new Set(sources.filter(Boolean))];
  const missing = uniqueSources.filter((text) => !translationCache.has(`tr:${language}:${text}`));
  if (missing.length) {
    const translated = await translateText(missing.join('\n'), language);
    const parts = translated.split('\n');
    if (parts.length === missing.length) missing.forEach((text, index) => translationCache.set(`tr:${language}:${text}`, parts[index]));
  }
  return sources.map((text) => translationCache.get(`tr:${language}:${text}`) || text);
}
function directTextNode(element) { return Array.from(element.childNodes).find((node) => node.nodeType === Node.TEXT_NODE && node.textContent.trim()); }
async function localizeLabels(language, requestId) {
  const elements = [
    ...document.querySelectorAll('.sidebar .brand small, .sidebar .nav-label, .sidebar .nav-item, .sidebar .notice strong, .sidebar .notice small, .safety-banner p, .safety-banner strong, #case-form .eyebrow, #case-form h2, #case-form .required, #case-form .field-hint, #case-form label, #guide-intro, .guide-top .eyebrow, .guide-top h2, .guide-footer span, #guide-actions button, #word-count, #patient-chip span, #generated-note span, #account-dialog .eyebrow, #account-dialog h2, #account-dialog p, #account-dialog label, #account-dialog button, #library-dialog .eyebrow, #library-dialog h2, #library-dialog .library-tabs button, #library-dialog .library-pane > .dialog-copy, #library-dialog .resource-form label, #library-dialog .resource-form .dialog-actions button'),
    ...document.querySelectorAll('#case-form textarea, #account-dialog input[placeholder], #library-dialog input[placeholder], #library-dialog textarea[placeholder]')
  ];
  const nodes = elements.map(directTextNode);
  const sourceTexts = nodes.map((node, index) => {
    if (!node) return elements[index].dataset.sourceText || '';
    const source = elements[index].dataset.sourceText || node.textContent.trim();
    elements[index].dataset.sourceText = source;
    return source;
  });
  const translated = await translateMany(sourceTexts, language);
  if (requestId !== localizationRequest) return;
  nodes.forEach((node, index) => { if (node && translated[index]) node.textContent = `${translated[index]} `; });
  const placeholders = Array.from(document.querySelectorAll('#case-form input[placeholder], #case-form textarea[placeholder], #account-dialog input[placeholder], #library-dialog input[placeholder], #library-dialog textarea[placeholder]'));
  const placeholderSources = placeholders.map((element) => element.dataset.sourcePlaceholder || element.placeholder);
  placeholderSources.forEach((source, index) => { placeholders[index].dataset.sourcePlaceholder = source; });
  const translatedPlaceholders = await translateMany(placeholderSources, language);
  if (requestId === localizationRequest) placeholders.forEach((element, index) => { element.placeholder = translatedPlaceholders[index]; });
}
async function localizeSelects(language, requestId) {
  const selects = [diagnosis, anesthesia, antibioticProphylaxis, skinPrep, centralLine, vteProphylaxis, procedure, ...dynamicFields.querySelectorAll('select')].filter(Boolean);
  const options = selects.flatMap((select) => Array.from(select.options));
  const sourceTexts = options.map((option) => option.dataset.sourceText || option.textContent);
  sourceTexts.forEach((source, index) => { options[index].dataset.sourceText = source; });
  const translated = await translateMany(sourceTexts, language);
  if (requestId === localizationRequest) options.forEach((option, index) => { option.textContent = translated[index]; });
}
async function localizeClinicalForm() {
  const requestId = ++localizationRequest;
  await Promise.all([localizeLabels(clinicalLanguage, requestId), localizeSelects(clinicalLanguage, requestId)]);
}
window.setClinicalLanguage = async (language) => {
  clinicalLanguage = language || 'tr';
  document.getElementById('today').textContent = new Intl.DateTimeFormat(clinicalLanguage, { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date());
  await localizeClinicalForm();
};

function renderOption(text) { return `<option value="${escapeHtml(text)}">${escapeHtml(text)}</option>`; }
function activeFields() { const usesProcedureSafetyFields = selectedSchema.fields.some((field) => field.id === 'criticalStructures'); return selectedSchema.fields.concat(usesProcedureSafetyFields ? [] : commonSafetyFields, commonOperativeFields); }
function populateDiagnoses() { diagnosis.innerHTML = '<option value="">Tanı seçiniz</option>' + diagnosisOrder.map((key) => `<option value="${key}">${schemas[key].label}</option>`).join(''); }
function renderFields() {
  dynamicFields.innerHTML = activeFields().map((field) => {
    if (field.type === 'select') {
      const options = ['<option value="">Belirtilmedi</option>'].concat(field.options.map(renderOption)).join('');
      return `<label>${field.label}<select id="field-${field.id}">${options}</select></label>`;
    }
    return `<label>${field.label}<input id="field-${field.id}" type="${field.type}" ${field.type === 'number' ? 'step="any"' : ''} placeholder="${field.placeholder || 'İsteğe bağlı'}"></label>`;
  }).join('');
}
function updateFlow() { selectedSchema = schemas[diagnosis.value]; if (!selectedSchema) { procedureSection.classList.add('hidden'); fieldsSection.classList.add('hidden'); generateButton.disabled = true; return; } procedure.innerHTML = selectedSchema.techniques.map(renderOption).join(''); procedureSection.classList.remove('hidden'); renderFields(); fieldsSection.classList.remove('hidden'); generateButton.disabled = false; const guideIntro = document.getElementById('guide-intro'); guideIntro.textContent = `${selectedSchema.label} için tekniğe özgü operatif bulguları isteğe bağlı olarak doldurun.`; delete guideIntro.dataset.sourceText; void localizeClinicalForm(); }
function values() { const result = {}; activeFields().forEach((field) => { result[field.id] = document.getElementById(`field-${field.id}`).value.trim(); }); return result; }
function countWords(text) { return text.trim().split(/\s+/).filter(Boolean).length; }
function finalSentence(label, value) { return `${label}: ${value.replace(/[.!?]+$/, '')}.`; }
function buildNote(v, procedureValue, anesthesiaValue, perioperative, extra, postop) {
  const preparation = [];
  const operativeDetails = [];
  const completion = [];
  if (anesthesiaValue) preparation.push(`Anestezi, ${lower(anesthesiaValue)} altında güvenle sağlandı.`);
  if (perioperative.antibiotic) preparation.push(perioperative.antibiotic === 'Endikasyon yoktu' ? 'Antibiyotik profilaksisi açısından ek endikasyon olmadığı değerlendirildi.' : `Cerrahi antibiyotik profilaksisi ${lower(perioperative.antibiotic)}.`);
  if (perioperative.skinPrep) preparation.push(`Cilt hazırlığı ${lower(perioperative.skinPrep)} ile tamamlandı.`);
  if (perioperative.centralLine) preparation.push(perioperative.centralLine === 'Yok' ? 'Santral venöz kateter mevcut değildi.' : `Santral venöz kateter ${lower(perioperative.centralLine)}.`);
  if (perioperative.vte) preparation.push(perioperative.vte === 'Endikasyon yoktu' ? 'Venöz tromboembolizm profilaksisi için ek endikasyon bulunmadığı değerlendirildi.' : `Profilaksi olarak ${lower(perioperative.vte)} uygulandı.`);
  preparation.push(OPENING_NOTE);
  operativeDetails.push(`Preoperatif tanı ${selectedSchema.label} olarak doğrulandı. Cerrahi güvenlik kontrolünü takiben ${procedureValue} tekniği ile planlanan girişime başlandı.`);
  activeFields().forEach((field) => { const raw = v[field.id]; if (!raw) return; const sentence = field.sentence(raw); if (sentence) operativeDetails.push(sentence); });
  if (operativeDetails.length > 1) operativeDetails.push('İşlem boyunca seçilen anatomik planlara sadık kalınarak, kaydedilen bulgular doğrultusunda güvenli diseksiyon ve onarım basamakları tamamlandı.');
  if (extra) completion.push(finalSentence('Ek bulgular ve intraoperatif değerlendirme', extra));
  if (postop) completion.push(finalSentence('Postoperatif plan', postop));
  completion.push(CLOSING_NOTE);
  return [preparation.join(' '), operativeDetails.join(' '), completion.join(' ')].filter(Boolean).join('\n\n');
}
async function generateNote(event) { event.preventDefault(); if (!selectedSchema || !form.reportValidity()) return; const v = values(); const perioperative = { antibiotic: antibioticProphylaxis.value, skinPrep: skinPrep.value, centralLine: centralLine.value, vte: vteProphylaxis.value }; const extra = document.getElementById('extra').value.trim(); const postop = document.getElementById('postop').value.trim(); const TurkishNote = buildNote(v, procedure.value, anesthesia.value, perioperative, extra, postop); generateButton.disabled = true; const note = clinicalLanguage === 'tr' ? TurkishNote : (await Promise.all(TurkishNote.split('\n\n').map((paragraph) => translateText(paragraph, clinicalLanguage, 'auto')))).join('\n\n'); generateButton.disabled = false; generatedNote.classList.remove('empty-note'); generatedNote.textContent = note; const words = countWords(note); const outsideTarget = words < 400 || words > 600; wordCount.textContent = outsideTarget ? `${words} kelime · hedef dışı` : `${words} kelime`; wordCount.classList.toggle('attention', outsideTarget); document.getElementById('patient-chip').innerHTML = `<i data-lucide="file-check-2"></i><span>${selectedSchema.label} · ${procedure.value}</span>`; document.getElementById('guide-intro').textContent = outsideTarget ? 'Not yalnızca girilen verilerle yazıldı. Hedef 400-600 kelimedir; yalnızca gerçek ek bulgu, ölçüm ve plan bilgilerini girerek ayrıntıyı tamamlayın.' : 'Taslak oluşturuldu. Seçtiğiniz tüm ölçüm ve operatif bulgular notta yer alıyor; klinik gerçeklerle karşılaştırıp gerekli alanları düzeltin.'; document.getElementById('guide-actions').classList.remove('hidden'); lucide.createIcons(); showToast(`${words} kelimelik taslak oluşturuldu`); }
function showToast(message) { toast.textContent = message; toast.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => toast.classList.remove('show'), 2800); }
diagnosis.addEventListener('change', updateFlow); form.addEventListener('submit', generateNote); document.getElementById('copy-note').addEventListener('click', async () => { await navigator.clipboard.writeText(generatedNote.textContent); showToast('Ameliyat notu panoya kopyalandı'); }); document.getElementById('print-note').addEventListener('click', () => window.print()); document.getElementById('clear-form').addEventListener('click', () => { form.reset(); diagnosis.value = ''; updateFlow(); generatedNote.className = 'generated-note empty-note'; generatedNote.innerHTML = '<i data-lucide="clipboard-list"></i><span>Ameliyat notu oluşturulmayı bekliyor.</span>'; wordCount.textContent = 'Hazır'; document.getElementById('guide-actions').classList.add('hidden'); document.getElementById('patient-chip').innerHTML = '<i data-lucide="file-pen-line"></i><span>Tanı seçimi bekleniyor</span>'; lucide.createIcons(); });
